76	std::string JsonErrorBody(const std::string& error, const std::string& detail = "") {
77	  std::string out = "{" + JsonStringPair("error", error);
78	  if (!detail.empty()) {
79	    out += "," + JsonStringPair("detail", detail);
80	  }
81	  out += "}";
