108	// 同理读一个浮点数：只接受 [-,+]digits[.digits][eE[+,-]digits] 的前缀。
109	double SafeScanDouble(const std::string& text, std::size_t from) {
110	  std::size_t i = from;
111	  while (i < text.size() && std::isspace(static_cast<unsigned char>(text[i]))) ++i;
112	  const std::size_t begin = i;
113	  if (i < text.size() && (text[i] == '-' || text[i] == '+')) ++i;
114	  bool digits = false;
115	  while (i < text.size() && std::isdigit(static_cast<unsigned char>(text[i]))) {
116	    ++i;
117	    digits = true;
118	  }
119	  if (i < text.size() && text[i] == '.') {
120	    ++i;
121	    while (i < text.size() && std::isdigit(static_cast<unsigned char>(text[i]))) {
122	      ++i;
123	      digits = true;
124	    }
125	  }
126	  if (!digits) return 0.0;
127	  if (i < text.size() && (text[i] == 'e' || text[i] == 'E')) {
128	    std::size_t j = i + 1;
129	    if (j < text.size() && (text[j] == '+' || text[j] == '-')) ++j;
130	    bool exp_digits = false;
131	    while (j < text.size() && std::isdigit(static_cast<unsigned char>(text[j]))) {
132	      ++j;
133	      exp_digits = true;
134	    }
135	    if (exp_digits) i = j;
136	  }
137	  const std::string num = text.substr(begin, i - begin);
138	  try {
139	    return std::stod(num);
140	  } catch (...) {
141	    // num 已由上面的正则式扫描保证形状合法，这里只是防御
142	    return 0.0;
143	  }
144	}
