291	  ~RestGatewayNode() override {
292	    running_ = false;
293	    if (server_fd_ >= 0) {
294	      ::shutdown(server_fd_, SHUT_RDWR);  // 唤醒阻塞在 accept 的线程
295	      close(server_fd_);
296	      server_fd_ = -1;
297	    }
298	    {
299	      std::lock_guard<std::mutex> lock(queue_mutex_);
300	      stopping_ = true;
301	      for (const int fd : pending_) {
302	        close(fd);  // 未处理的连接直接断开
303	      }
304	      pending_.clear();
305	    }
306	    queue_cv_.notify_all();
307	    if (server_thread_.joinable()) {
308	      server_thread_.join();
309	    }
310	    for (auto& worker : workers_) {
311	      if (worker.joinable()) {
312	        worker.join();
313	      }
