422	  // ---------------------------------------------------------------------------
423	  // 请求读取：头部上限、请求体上限、Content-Length 严格解析、分块传输拒绝
424	  // ---------------------------------------------------------------------------
425	  enum class ReadStatus { kOk, kClosed, kBadRequest, kTooLarge };
426	
427	  ReadStatus ReadRequest(int client_fd, HttpRequest* out) {
428	    std::string raw;
429	    raw.reserve(1024);
430	    char buffer[4096];
431	
432	    // 1) 读到头部结束标记
433	    std::size_t header_end = std::string::npos;
434	    while (true) {
435	      header_end = raw.find("\r\n\r\n");
436	      if (header_end != std::string::npos) {
437	        break;
438	      }
439	      if (raw.size() > kMaxHeaderBytes) {
440	        return ReadStatus::kBadRequest;
441	      }
442	      const ssize_t n = ::read(client_fd, buffer, sizeof(buffer));
443	      if (n == 0) {
444	        return ReadStatus::kClosed;
445	      }
446	      if (n < 0) {
447	        if (errno == EINTR) continue;
448	        return ReadStatus::kClosed;  // 超时(EAGAIN) 或对端重置
449	      }
450	      raw.append(buffer, static_cast<std::size_t>(n));
451	    }
452	    if (header_end > kMaxHeaderBytes) {
453	      return ReadStatus::kBadRequest;  // 头部过大
454	    }
455	    const std::string head = raw.substr(0, header_end);
456	
457	    // 2) 请求行
458	    std::istringstream first_line(head.substr(0, head.find("\r\n")));
459	    std::string version;
460	    first_line >> out->method >> out->target >> version;
461	    if (out->method.empty() || out->target.empty()) {
462	      return ReadStatus::kBadRequest;
463	    }
464	    out->path = RequestPathOnly(out->target);
465	    out->query = RequestQueryOnly(out->target);
466	    FindHeaderValue(head, "Authorization", &out->authorization);
467	
468	    // 3) 请求体长度：分块传输不支持（猜长度 = 读到连接耗尽，直接拒绝）
469	    if (HasChunkedTransferEncoding(head)) {
470	      return ReadStatus::kBadRequest;
471	    }
472	    std::size_t content_length = 0;
473	    std::string cl_value;
474	    if (FindHeaderValue(head, "Content-Length", &cl_value)) {
475	      switch (ParseContentLength(cl_value, &content_length)) {
476	        case ContentLengthStatus::kOk:
477	          break;
478	        case ContentLengthStatus::kMissing:
479	          content_length = 0;
480	          break;
481	        case ContentLengthStatus::kTooLarge:
482	          return ReadStatus::kTooLarge;
483	        case ContentLengthStatus::kInvalid:
484	          return ReadStatus::kBadRequest;
485	      }
486	    }
487	
488	    // 4) 读满请求体（总字节数同样受上限约束）
489	    const std::size_t body_begin = header_end + 4;
490	    std::size_t body_size = raw.size() - body_begin;
491	    if (body_size > content_length) {
492	      body_size = content_length;  // 多读的属于下一个请求（本网关一连接一请求，丢弃）
493	    }
494	    while (body_size < content_length) {
495	      const ssize_t n = ::read(client_fd, buffer, sizeof(buffer));
496	      if (n == 0) {
497	        return ReadStatus::kBadRequest;  // 声明了长度却提前断开
498	      }
499	      if (n < 0) {
500	        if (errno == EINTR) continue;
501	        return ReadStatus::kClosed;
502	      }
503	      body_size += static_cast<std::size_t>(n);
504	      raw.append(buffer, static_cast<std::size_t>(n));
505	      if (body_size > kMaxRequestBytes) {
506	        return ReadStatus::kTooLarge;
507	      }
508	    }
509	    out->body = raw.substr(body_begin, content_length);
510	    return ReadStatus::kOk;
511	  }
