514	  // 请求分发
515	  // ---------------------------------------------------------------------------
516	  void HandleClient(int client_fd) {
517	    HttpRequest req;
518	    const ReadStatus status = ReadRequest(client_fd, &req);
519	    if (status == ReadStatus::kClosed) {
520	      return;  // 对端没发完整请求就断了：静默关闭
521	    }
522	    if (status == ReadStatus::kBadRequest) {
523	      HttpResponse resp;
524	      resp.status = "400 Bad Request";
525	      resp.body = JsonErrorBody("bad_request");
526	      RecordRequestStatus(resp.status);
527	      WriteAll(client_fd, SerializeResponse(resp, false));
528	      DrainForClose(client_fd, 64U * 1024U);
529	      return;
530	    }
531	    if (status == ReadStatus::kTooLarge) {
532	      HttpResponse resp;
533	      resp.status = "413 Payload Too Large";
534	      resp.body = JsonErrorBody("payload_too_large");
535	      RecordRequestStatus(resp.status);
536	      WriteAll(client_fd, SerializeResponse(resp, false));
537	      DrainForClose(client_fd);
538	      return;
539	    }
540	
541	    if (req.method == "OPTIONS") {
542	      HttpResponse resp;
543	      resp.status = "204 No Content";
544	      resp.body.clear();
545	      resp.content_type.clear();
546	      RecordRequestStatus(resp.status);
547	      WriteAll(client_fd, SerializeResponse(resp, true));
548	      return;
549	    }
550	
551	    // 鉴权中间件：auth_token 为空时 IsAuthorized 恒真（默认关闭）
552	    if (!IsAuthExemptPath(req.path) && !Authorize(req)) {
553	      HttpResponse resp;
554	      resp.status = "401 Unauthorized";
555	      resp.body = JsonErrorBody("unauthorized");
556	      std::string raw = "HTTP/1.1 401 Unauthorized\r\n";
557	      raw += "Content-Type: application/json\r\n";
558	      raw += "Content-Length: " + std::to_string(resp.body.size()) + "\r\n";
559	      raw += "WWW-Authenticate: Bearer\r\n";
560	      raw += ExtraHeaders();
561	      raw += "Connection: close\r\n\r\n";
562	      raw += resp.body;
563	      RecordRequestStatus(resp.status);
564	      WriteAll(client_fd, raw);
565	      return;
566	    }
567	
568	    const HttpResponse resp = Dispatch(req);
569	    RecordRequestStatus(resp.status);
570	    WriteAll(client_fd, SerializeResponse(resp, true));
571	  }
