573	  // 状态码按前三位归类（"200 OK" -> "200"），保证指标标签基数有限
574	  void RecordRequestStatus(const std::string& status) {
575	    const std::string code = status.substr(0, std::min<std::size_t>(3, status.size()));
576	    std::lock_guard<std::mutex> lock(data_mutex_);
577	    ++request_counts_[code];
578	  }
