591	  HttpResponse Dispatch(const HttpRequest& req) {
592	    HttpResponse resp;
593	    const std::string& method = req.method;
594	    const std::string& path = req.path;
595	
596	    // 精确路由：旧实现用 find() 子串匹配，/api/v1/ordersXYZ 也会命中订单路由
597	    if (method == "GET" && PathMatchesAny(path, "/", "/index.html")) {
598	      resp.content_type = "text/html; charset=utf-8";
599	      resp.body = ReadStaticHtml();
600	      if (resp.body.empty()) {
601	        resp.status = "404 Not Found";
602	        resp.content_type = "text/html; charset=utf-8";
603	        resp.body = "<h1>404 Not Found: operator_console.html</h1>";
604	      }
605	      return resp;
606	    }
607	    if (method == "GET" && PathMatchesAny(path, "/api/operator/snapshot", "/api/v1/state")) {
608	      resp.body = FormatSnapshotJson();
609	      return resp;
610	    }
611	    if (method == "GET" && PathMatches(path, "/api/v1/vehicle_links")) {
612	      resp.body = FormatVehicleLinksJson();
613	      return resp;
614	    }
615	    if (method == "POST" && PathMatches(path, "/api/v1/force_clear_link")) {
616	      return HandleForceClear(req);
617	    }
618	    if (method == "POST" && PathMatches(path, "/api/v1/restore_link")) {
619	      return HandleRestore(req);
620	    }
621	    if (method == "GET" && PathMatches(path, "/metrics")) {
622	      resp.status = "200 OK";
623	      resp.content_type = "text/plain; version=0.0.4; charset=utf-8";
624	      resp.body = RenderMetrics();
625	      return resp;
626	    }
627	    if (method == "GET" && PathMatches(path, "/api/system/ready")) {
628	      return HandleReadiness();
629	    }
630	    if (method == "POST" && PathMatches(path, "/api/v1/orders")) {
631	      return HandleSubmitOrder(req);
632	    }
633	    if (method == "POST" && PathMatchesAny(path, "/api/v1/cancel", "/api/workflows/cancel")) {
634	      return HandleCancel(req);
635	    }
636	    if (method == "POST" && PathMatches(path, "/api/operator/estop")) {
637	      std_msgs::msg::Bool estop_msg;
638	      estop_msg.data = true;
639	      estop_pub_->publish(estop_msg);
640	      resp.body = "{\"status\":\"ok\",\"estop_engaged\":true}";
641	      return resp;
642	    }
643	    if (method == "POST" && PathMatches(path, "/api/v1/map/upload")) {
644	      return HandleMapUpload(req);
645	    }
646	
647	    resp.status = "404 Not Found";
648	    resp.body = JsonErrorBody("not_found");
649	    return resp;
650	  }
