669	    if (!force_clear_cli_->wait_for_service(1s)) {
670	      resp.status = "503 Service Unavailable";
671	      resp.body = JsonErrorBody("service_unavailable");
672	      return resp;
673	    }
674	    auto fut = force_clear_cli_->async_send_request(request);
675	    if (fut.wait_for(2s) != std::future_status::ready) {
676	      resp.status = "504 Gateway Timeout";
677	      resp.body = JsonErrorBody("timeout");
678	      return resp;
679	    }
680	    auto res = fut.get();
681	    std::string body = "{\"status\":\"" + std::string(res->success ? "ok" : "rejected") + "\",";
682	    body += JsonStringPair("message", res->message) + ",\"quarantined\":";
683	    body += (res->quarantined ? "true" : "false");
684	    body += ",\"released_resources\":[";
685	    for (std::size_t i = 0; i < res->released_resources.size(); ++i) {
686	      if (i) body += ",";
687	      body += "\"" + JsonEscape(res->released_resources[i]) + "\"";
688	    }
689	    body += "]}";
690	    resp.body = body;
691	    if (!res->success) {
692	      resp.status = "409 Conflict";
693	    }
694	    return resp;
