905	  // 一键热上传与地图骨架拓扑生成
906	  // ---------------------------------------------------------------------------
907	  HttpResponse HandleMapUpload(const HttpRequest& req) {
908	    HttpResponse resp;
909	    const std::string& body = req.body;
910	
911	    auto find_value_pos = [&body](const std::string& key) -> std::size_t {
912	      const auto pos = body.find("\"" + key + "\"");
913	      if (pos == std::string::npos) return std::string::npos;
914	      const auto colon = body.find(':', pos);
915	      if (colon == std::string::npos) return std::string::npos;
916	      return colon + 1;
917	    };
918	    auto get_int = [&](const std::string& key, long long def) -> long long {
919	      const auto pos = find_value_pos(key);
920	      if (pos == std::string::npos) return def;
921	      const long long value = SafeScanInt(body, pos);
922	      return value == 0 ? def : value;
923	    };
924	    auto get_double = [&](const std::string& key, double def) -> double {
925	      const auto pos = find_value_pos(key);
926	      if (pos == std::string::npos) return def;
927	      const double value = SafeScanDouble(body, pos);
928	      return value == 0.0 ? def : value;
929	    };
930	
931	    const long long width = get_int("width", 0);
932	    const long long height = get_int("height", 0);
933	    const double res = get_double("resolution", 0.05);
934	    const double origin_x = get_double("origin_x", 0.0);
935	    const double origin_y = get_double("origin_y", 0.0);
936	
937	    if (width <= 0 || height <= 0) {
938	      resp.status = "400 Bad Request";
939	      resp.body = JsonErrorBody("invalid_dimensions");
940	      return resp;
941	    }
942	    // 尺寸上限：width*height 会直接决定内存分配，不能让请求方随便点
943	    const long long cells = width * height;
944	    if (cells <= 0 || cells > 4000000LL) {  // 4M 格 ≈ 2000x2000
945	      resp.status = "413 Payload Too Large";
946	      resp.body = JsonErrorBody("grid_too_large");
947	      return resp;
948	    }
949	
950	    amr_dispatcher_core::planning::MapGrid grid;
951	    grid.width = static_cast<uint32_t>(width);
952	    grid.height = static_cast<uint32_t>(height);
953	    grid.resolution = res;
954	    grid.origin_x = origin_x;
955	    grid.origin_y = origin_y;
956	    grid.origin_yaw = 0.0;
957	    grid.data.assign(static_cast<std::size_t>(cells), 0);  // 默认为空闲通行区
958	
959	    const auto grid_pos = body.find("\"grid_data\"");
960	    if (grid_pos != std::string::npos) {
961	      const auto arr_start = body.find('[', grid_pos);
962	      const auto arr_end = body.find(']', arr_start);
963	      if (arr_start != std::string::npos && arr_end != std::string::npos) {
964	        const std::string arr_str = body.substr(arr_start + 1, arr_end - arr_start - 1);
965	        std::stringstream ss(arr_str);
966	        std::string item;
967	        std::size_t idx = 0;
968	        while (std::getline(ss, item, ',') && idx < grid.data.size()) {
969	          // 解析失败按 0（空闲）处理：旧实现对异常是 try/catch 吞掉
970	          grid.data[idx++] = static_cast<int8_t>(SafeScanInt(item, 0));
971	        }
972	      }
973	    }
974	
975	    std::vector<amr_dispatcher_core::planning::AnchorStation> anchors;
976	    const auto anchors_pos = body.find("\"anchors\"");
977	    if (anchors_pos != std::string::npos) {
978	      const auto arr_start = body.find('[', anchors_pos);
979	      const auto arr_end = body.find(']', arr_start);
980	      if (arr_start != std::string::npos && arr_end != std::string::npos) {
981	        const std::string arr_str = body.substr(arr_start + 1, arr_end - arr_start - 1);
982	        std::size_t obj_start = 0;
983	        while ((obj_start = arr_str.find('{', obj_start)) != std::string::npos) {
984	          const std::size_t obj_end = arr_str.find('}', obj_start);
985	          if (obj_end == std::string::npos) break;
986	          const std::string obj_str = arr_str.substr(obj_start, obj_end - obj_start + 1);
987	
988	          auto extract_str = [&obj_str](const std::string& k) -> std::string {
989	            const auto p = obj_str.find("\"" + k + "\"");
990	            if (p == std::string::npos) return "";
991	            const auto colon = obj_str.find(':', p);
992	            if (colon == std::string::npos) return "";
993	            const auto q1 = obj_str.find('\"', colon);
994	            if (q1 == std::string::npos) return "";
995	            const auto q2 = obj_str.find('\"', q1 + 1);
996	            if (q2 == std::string::npos) return "";
997	            return obj_str.substr(q1 + 1, q2 - q1 - 1);
998	          };
999	          auto extract_num = [&obj_str](const std::string& k) -> double {
1000	            const auto p = obj_str.find("\"" + k + "\"");
1001	            if (p == std::string::npos) return 0.0;
1002	            const auto colon = obj_str.find(':', p);
1003	            if (colon == std::string::npos) return 0.0;
1004	            return SafeScanDouble(obj_str, colon + 1);
1005	          };
1006	
1007	          amr_dispatcher_core::planning::AnchorStation a;
1008	          a.id = extract_str("id");
1009	          a.type = extract_str("type");
1010	          if (a.type.empty()) a.type = "normal";
1011	          a.x = extract_num("x");
1012	          a.y = extract_num("y");
1013	          a.yaw = extract_num("yaw");
1014	          if (!a.id.empty()) {
1015	            anchors.push_back(a);
1016	          }
1017	          obj_start = obj_end + 1;
1018	        }
1019	      }
1020	    }
1021	
1022	    // 核心库自动化流水线：腐蚀 -> 细化 -> 剪枝 -> 拓扑构建
1023	    amr_dispatcher_core::planning::SafetyFilterConfig sf_cfg;
1024	    sf_cfg.robot_radius_m = 0.25;
1025	    sf_cfg.safety_margin_m = 0.05;
1026	    const auto safe_grid = amr_dispatcher_core::planning::FilterSafetySpace(grid, sf_cfg);
1027	    const auto skel = amr_dispatcher_core::planning::ZhangSuenThinning(safe_grid);
1028	
1029	    std::vector<amr_dispatcher_core::planning::PixelCoord> protected_points;
1030	    for (const auto& a : anchors) {
1031	      const amr_dispatcher_core::planning::WorldCoord w{a.x, a.y};
1032	      protected_points.push_back(amr_dispatcher_core::planning::WorldToPixel(w, grid));
1033	    }
1034	    amr_dispatcher_core::planning::PruneConfig pr_cfg;
1035	    pr_cfg.min_branch_length_m = 0.5;
1036	    pr_cfg.resolution = res;
1037	    const auto pruned =
1038	        amr_dispatcher_core::planning::PruneSkeletonProtected(skel, protected_points, pr_cfg);
1039	
1040	    amr_dispatcher_core::planning::TopologyBuilderConfig tb_cfg;
1041	    tb_cfg.max_snap_dist_m = 3.0;
1042	    tb_cfg.map_hash = "web_upload_" + std::to_string(width) + "x" + std::to_string(height);
1043	    tb_cfg.graph_version = "v1_web";
1044	    const auto build_res =
1045	        amr_dispatcher_core::planning::BuildTopologyCatalog(pruned, grid, anchors, tb_cfg);
1046	
1047	    if (!build_res.success) {
1048	      resp.status = "422 Unprocessable Entity";
1049	      resp.body = "{\"status\":\"error\"," + JsonStringPair("message", build_res.error_message) + "}";
1050	      return resp;
1051	    }
1052	
1053	    // 写入 config/generated/stations.yaml (tmp + rename 原子替换)
1054	    const std::filesystem::path final_path("config/generated/stations.yaml");
1055	    std::filesystem::create_directories(final_path.parent_path());
1056	    const std::filesystem::path tmp_path("config/generated/stations.yaml.tmp");
1057	    {
1058	      std::ofstream out(tmp_path);
1059	      out << "version:\n";
1060	      out << "  map_hash: \"" << build_res.catalog.map_hash << "\"\n";
1061	      out << "  graph_version: \"" << build_res.catalog.graph_version << "\"\n";
1062	      out << "stations:\n";
1063	      for (const auto& s : build_res.catalog.stations) {
1064	        out << "  - id: \"" << s.id << "\"\n";
1065	        out << "    x: " << s.x << "\n";
1066	        out << "    y: " << s.y << "\n";
1067	        out << "    yaw: " << s.yaw << "\n";
1068	        out << "    type: \"" << s.type << "\"\n";
1069	      }
1070	      out << "road_nodes:\n";
1071	      for (const auto& rn : build_res.catalog.road_nodes) {
1072	        out << "  - id: \"" << rn.id << "\"\n";
1073	        out << "    x: " << rn.x << "\n";
1074	        out << "    y: " << rn.y << "\n";
1075	        out << "    yaw: " << rn.yaw << "\n";
1076	      }
1077	      out << "edges:\n";
1078	      for (const auto& e : build_res.catalog.edges) {
1079	        out << "  - from: \"" << e.from << "\"\n";
1080	        out << "    to: \"" << e.to << "\"\n";
1081	        out << "    distance_m: " << e.distance_m << "\n";
1082	        out << "    bidirectional: " << (e.bidirectional ? "true" : "false") << "\n";
1083	        out << "    enabled: true\n";
1084	        out << "    polyline:\n";
1085	        for (const auto& pt : e.polyline) {
1086	          out << "      - [" << pt.first << ", " << pt.second << "]\n";
1087	        }
1088	      }
1089	      out.close();
1090	    }
1091	    std::error_code rename_ec;
1092	    std::filesystem::rename(tmp_path, final_path, rename_ec);
1093	    if (rename_ec) {
1094	      resp.status = "500 Internal Server Error";
1095	      resp.body = JsonErrorBody("stations_write_failed", rename_ec.message());
1096	      return resp;
1097	    }
1098	
1099	    resp.body = "{\"status\":\"ok\",\"stations_count\":" +
1100	                std::to_string(build_res.catalog.stations.size()) +
1101	                ",\"road_nodes_count\":" + std::to_string(build_res.catalog.road_nodes.size()) +
1102	                ",\"edges_count\":" + std::to_string(build_res.catalog.edges.size()) + "," +
1103	                JsonStringPair("map_hash", build_res.catalog.map_hash) + "}";
