1175	  static std::string GetQueryParam(const std::string& query, const std::string& key,
1176	                                   const std::string& fallback = "") {
1177	    const std::string target = key + "=";
1178	    auto pos = query.find(target);
1179	    // 只认 "key="（前面必须是查询串开头或 '&'），避免 "xid=" 命中 "id="
1180	    while (pos != std::string::npos) {
1181	      if (pos == 0 || query[pos - 1] == '&') {
1182	        break;
1183	      }
1184	      pos = query.find(target, pos + 1);
1185	    }
1186	    if (pos == std::string::npos) return fallback;
1187	    const auto amp = query.find('&', pos);
1188	    if (amp == std::string::npos) {
1189	      return query.substr(pos + target.size());
1190	    }
1191	    return query.substr(pos + target.size(), amp - (pos + target.size()));
1192	  }
