22	 * 实施严格的拓扑依赖启动与停止链：
23	 * ChassisDriver (Active) -> SafetyGate (Ready) -> PathTracker (Ready) -> DispatcherNode (Active)
24	 * 向上暴露统一的 `/system/ready` 与 `/system/healthy` 服务，供上层 WMS/REST 网关拦截派单。
25	 */
26	class LifecycleCoordinatorNode : public rclcpp::Node {
27	 public:
28	  explicit LifecycleCoordinatorNode(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
29	      : rclcpp::Node("lifecycle_coordinator_node", options) {
30	    declare_parameter("auto_bringup", true);
31	    declare_parameter("check_period_ms", 500);
32	
33	    auto_bringup_ = get_parameter("auto_bringup").as_bool();
34	    int period_ms = get_parameter("check_period_ms").as_int();
35	
36	    dispatcher_get_state_cli_ =
37	        create_client<lifecycle_msgs::srv::GetState>("/dispatcher_node/get_state");
38	    dispatcher_change_state_cli_ =
39	        create_client<lifecycle_msgs::srv::ChangeState>("/dispatcher_node/change_state");
40	
41	    safety_sub_ = create_subscription<amr_dispatcher_interfaces::msg::SafetyState>(
42	        "/safety/state", 10,
43	        [this](const amr_dispatcher_interfaces::msg::SafetyState::SharedPtr msg) {
44	          safety_healthy_ = msg->motion_allowed;
45	          safety_seen_ = true;
46	        });
47	
48	    readiness_srv_ = create_service<amr_dispatcher_interfaces::srv::GetSystemReadiness>(
49	        "/system/ready",
50	        [this](const std::shared_ptr<amr_dispatcher_interfaces::srv::GetSystemReadiness::Request> /*req*/,
51	               std::shared_ptr<amr_dispatcher_interfaces::srv::GetSystemReadiness::Response> resp) {
52	          EvaluateReadiness(resp);
53	        });
54	
55	    healthy_srv_ = create_service<amr_dispatcher_interfaces::srv::GetSystemReadiness>(
56	        "/system/healthy",
57	        [this](const std::shared_ptr<amr_dispatcher_interfaces::srv::GetSystemReadiness::Request> /*req*/,
58	               std::shared_ptr<amr_dispatcher_interfaces::srv::GetSystemReadiness::Response> resp) {
59	          EvaluateReadiness(resp);
60	        });
61	
62	    ready_pub_ = create_publisher<std_msgs::msg::Bool>("/system/ready_flag", rclcpp::QoS(1).transient_local());
63	
64	    timer_ = create_wall_timer(
65	        std::chrono::milliseconds(period_ms),
66	        std::bind(&LifecycleCoordinatorNode::CoordinatorTick, this));
67	
68	    RCLCPP_INFO(get_logger(), "Lifecycle Coordinator & Readiness Probe initialized (auto_bringup=%s)",
69	                auto_bringup_ ? "true" : "false");
70	  }
71	
72	 private:
73	  void CoordinatorTick() {
74	    if (!dispatcher_get_state_cli_->service_is_ready()) {
75	      return;
76	    }
77	
78	    // 1. 获取 dispatcher_node 当前生命周期状态。
79	    //    单线程 executor 下 spin 期间不能嵌套 wait_for future（会永久阻塞），
80	    //    必须异步发送 + 轮询 shared_future 的就绪位。
81	    if (!pending_get_state_.valid()) {
82	      auto req = std::make_shared<lifecycle_msgs::srv::GetState::Request>();
83	      pending_get_state_ = dispatcher_get_state_cli_->async_send_request(req).share();
84	      return;
85	    }
86	
87	    if (pending_get_state_.wait_for(std::chrono::seconds(0)) != std::future_status::ready) {
88	      // 尚未返回，下一拍再看；超时则放弃本次请求避免悬挂
89	      if (++get_state_wait_ticks_ > 10) {
90	        pending_get_state_ = {};
91	        get_state_wait_ticks_ = 0;
92	      }
93	      return;
94	    }
95	    current_dispatcher_state_ = pending_get_state_.get()->current_state.label;
96	    pending_get_state_ = {};
97	    get_state_wait_ticks_ = 0;
98	
99	    // 2. 自动级联提拉状态机: unconfigured -> inactive -> active
100	    if (auto_bringup_) {
101	      if (current_dispatcher_state_ == "unconfigured") {
102	        RCLCPP_INFO(get_logger(), "Promoting dispatcher_node: unconfigured -> configure()");
103	        SendTransition(lifecycle_msgs::msg::Transition::TRANSITION_CONFIGURE);
104	      } else if (current_dispatcher_state_ == "inactive") {
105	        RCLCPP_INFO(get_logger(), "Promoting dispatcher_node: inactive -> activate()");
106	        SendTransition(lifecycle_msgs::msg::Transition::TRANSITION_ACTIVATE);
107	      }
108	    }
109	
110	    // 3. 周期广播整体就绪状态布尔量
111	    std_msgs::msg::Bool ready_msg;
112	    ready_msg.data = (current_dispatcher_state_ == "active");
113	    ready_pub_->publish(ready_msg);
114	  }
115	
116	  void SendTransition(uint8_t transition_id) {
117	    if (!dispatcher_change_state_cli_->service_is_ready()) return;
118	    auto req = std::make_shared<lifecycle_msgs::srv::ChangeState::Request>();
119	    req->transition.id = transition_id;
120	    dispatcher_change_state_cli_->async_send_request(req);
121	  }
122	
123	  void EvaluateReadiness(std::shared_ptr<amr_dispatcher_interfaces::srv::GetSystemReadiness::Response> resp) {
124	    bool is_ready = (current_dispatcher_state_ == "active") && safety_seen_ && safety_healthy_;
125	    resp->ready = is_ready;
126	    resp->healthy = safety_healthy_;
127	
128	    if (is_ready) {
129	      resp->state = "READY";
130	      resp->message = "All critical nodes (Chassis, Safety, Dispatcher) are ACTIVE and HEALTHY";
131	      resp->active_nodes = {"chassis_driver", "safety_gate", "path_tracker", "dispatcher_node"};
132	    } else if (current_dispatcher_state_ != "active") {
133	      resp->state = "INITIALIZING";
134	      resp->message = "DispatcherNode is in state: " + current_dispatcher_state_;
135	      resp->pending_nodes = {"dispatcher_node"};
136	    } else {
137	      resp->state = "DEGRADED";
138	      resp->message = "Safety Gate or Chassis reporting fault/standstill";
139	    }
140	  }
141	
142	  bool auto_bringup_{true};
143	  std::string current_dispatcher_state_{"unknown"};
144	  bool safety_seen_{false};
145	  bool safety_healthy_{true};
146	  std::shared_future<lifecycle_msgs::srv::GetState::Response::SharedPtr> pending_get_state_;
147	  int get_state_wait_ticks_ = 0;
148	
149	  rclcpp::Client<lifecycle_msgs::srv::GetState>::SharedPtr dispatcher_get_state_cli_;
150	  rclcpp::Client<lifecycle_msgs::srv::ChangeState>::SharedPtr dispatcher_change_state_cli_;
151	  rclcpp::Subscription<amr_dispatcher_interfaces::msg::SafetyState>::SharedPtr safety_sub_;
152	
153	  rclcpp::Service<amr_dispatcher_interfaces::srv::GetSystemReadiness>::SharedPtr readiness_srv_;
154	  rclcpp::Service<amr_dispatcher_interfaces::srv::GetSystemReadiness>::SharedPtr healthy_srv_;
155	  rclcpp::Publisher<std_msgs::msg::Bool>::SharedPtr ready_pub_;
156	  rclcpp::TimerBase::SharedPtr timer_;
157	};
158	
159	}  // namespace amr_dispatcher_ros
160	
161	int main(int argc, char* argv[]) {
162	  rclcpp::init(argc, argv);
163	  auto node = std::make_shared<amr_dispatcher_ros::LifecycleCoordinatorNode>();
164	  rclcpp::spin(node);
165	  rclcpp::shutdown();
166	  return 0;
167	}
